            {
                Dlg.Show("Nenhuma placa de video foi detectada.\nRode como administrador e confira a pasta libs.", "BunoTunner");
            }

            timer.Interval = 1000;
            timer.Tick += delegate { try { Tick(); } catch (Exception) { } };
            timer.Start();
            FormClosing += OnClosing;
            InitTray();
        }

