        static readonly int[] BenchPos = { 1, 0, 4, 2, 3 };   // posicao de cada teste (indice: 0 GPU, 1 CPU, 2 FPU, 3 RAM, 4 SSD) -> CPU, GPU, RAM, SSD, FPU
