        {
            XpGroup g = new XpGroup(); g.Title = title; g.SetBounds(0, BenchPos[k] * 74, 676, 70);
            XpIconButton b = new XpIconButton(icon, 48); b.Location = new Point(12, 19); b.Badge = 1;
